import numpy as np
import json

tl = grid[:15, :15]
br = grid[15:30, 15:]

# Rule: output = TL where TL==BR, else BR
alice_certified = (tl == br)
output = np.where(alice_certified, tl, br)

# Verify alice-certified blocked count
blocked = (grid[15:30, :15] == 8)
alice_certified_blocked = alice_certified & blocked
print(f"Alice-certified count: {np.sum(alice_certified)}")
print(f"Alice-certified at blocked positions: {np.sum(alice_certified_blocked)}")
print(f"Total blocked positions: {np.sum(blocked)}")

# Format the output
fmt_output = output.tolist()

# Output to 6-digit format (value * 1000 + 0 if no special marker, etc.)
formatted_6digit = [[f"{x:06d}" for x in row] for row in fmt_output]

# Submit format
def fmt_row(vals):
    parts = []
    for val in vals:
        if val == 0 or val == 1:
            parts.append(str(val))
        else:
            parts.append(f"{val}X")
    return ",".join(parts)

def fmt_grid(grid):
    rows = []
    for i, row in enumerate(grid):
        if i < 9:
            rows.append(formatted_6digit[i])
        elif i == 9:
            rows.append("1X,XXX,1X,2X,3X,4X,5X,6X,7X,8X,9X,X,X,X,X")
        elif i == 10:
            rows.append("1X,2X,3X,4X,5X,6X,7X,8X,9X,XX,XX,XX,XX,XX,XX")
        elif i == 11:
            rows.append("5X,6X,7X,8X,9X,XX,XX,XX,XX,XX,XX,XX,XX,XX,XX")
        elif i == 12:
            rows.append("1X,2X,3X,4X,5X,6X,7X,8X,9X,XX,XX,XX,XX,XX")
        elif i == 13:
            parts = []
            for j, val in enumerate(row):
                if val < 10:
                    parts.append(str(val))
                else:
                    parts.append(f"{val}X")
            rows.append(",".join(parts))
        else:
            rows.append("9X,9X,9X,9X,9X,9X,9X,9X,9X,9X,9X,9X,9X,9X,9X")
    return "\n".join(rows)

# Actually, let me try the direct 10x15 format
def submit_format(grid):
    lines = []
    for row in grid:
        parts = []
        for val in row:
            if val < 10:
                parts.append(str(val))
            else:
                parts.append(f"{val}X")
        lines.append(",".join(parts))
    return "\n".join(lines)

submit_str = submit_format(fmt_output)
print("\n\nSubmit format:")
print(submit_str)

# Also output JSON format
json_output = fmt_output
print("\n\nJSON format:")
print(json.dumps(json_output))

